<template><div v-if="data"><div class="admin-page-head"><div><h1>{{ data.user.first_name }} {{ data.user.last_name||'' }}</h1><p>{{ data.user.email||data.user.phone }} · {{ data.user.role }}</p></div><div class="head-actions"><select v-model="editRole" class="select"><option value="user">User</option><option value="manager">Manager</option><option value="editor">Editor</option><option value="admin">Admin</option></select><select v-model="editStatus" class="select"><option value="active">Активен</option><option value="suspended">Заблокирован</option></select><button class="btn primary" :disabled="saving" @click="save">{{ saving ? "Сохраняем…" : "Сохранить" }}</button><NuxtLink class="btn" to="/admin/users">← Пользователи</NuxtLink></div></div><div class="admin-grid four"><div class="admin-card"><div class="metric-label">Статус</div><div class="metric-value" style="font-size:20px">{{ data.user.status }}</div></div><div class="admin-card"><div class="metric-label">Регистрация</div><div class="metric-value" style="font-size:20px">{{ date(data.user.created_at) }}</div></div><div class="admin-card"><div class="metric-label">Бронирований</div><div class="metric-value">{{ data.bookings.length }}</div></div><div class="admin-card"><div class="metric-label">Поездок</div><div class="metric-value">{{ completed }}</div></div></div><div class="admin-grid two" style="margin-top:16px"><section class="admin-card"><h3>История поездок</h3><div class="list"><div v-for="b in data.bookings" :key="b.id" class="list-row"><div><b>{{ b.title }}</b><div class="muted">{{ b.destination }} · {{ b.hotel }}</div><div class="muted">{{ date(b.departure_date) }} · {{ b.duration }} ночей · {{ b.status }}</div></div><strong>{{ money(b.price) }}</strong></div><div v-if="!data.bookings.length" class="empty">Пользователь ещё ничего не бронировал</div></div></section><section class="admin-card"><h3>Активность</h3><div class="list"><div v-for="a in data.activity" :key="`${a.created_at}-${a.event}`" class="list-row"><div><b>{{ labels[a.event]||a.event }}</b><div class="muted">{{ JSON.stringify(a.payload) }}</div></div><span class="muted">{{ dateTime(a.created_at) }}</span></div><div v-if="!data.activity.length" class="empty">История активности пока пуста</div></div></section></div></div><div v-else class="admin-card empty">Пользователь не найден.</div></template>
<script setup lang="ts">
definePageMeta({layout:'admin',middleware:'admin'});const api=useApi();const route=useRoute();const data=ref<any>(null);const saving=ref(false);const editRole=ref<any>('user');const editStatus=ref<any>('active');data.value=await api(`/api/admin/users/${route.params.id}`).catch(()=>null);if(data.value){editRole.value=data.value.user.role;editStatus.value=data.value.user.status}
const save=async()=>{saving.value=true;try{const r=await api<any>(`/api/admin/users/${route.params.id}`,{method:'PATCH',body:{role:editRole.value,status:editStatus.value}});data.value.user.role=r.user.role;data.value.user.status=r.user.status}finally{saving.value=false}}
const completed=computed(()=>data.value?.bookings?.filter((x:any)=>['confirmed','provider_booking','completed'].includes(x.status)).length||0);const money=(v:number)=>new Intl.NumberFormat('ru-RU').format(v||0)+' ₽';const date=(v:string)=>new Date(v).toLocaleDateString('ru-RU');const dateTime=(v:string)=>new Date(v).toLocaleString('ru-RU');const labels:any={search_submitted:'Поиск',offer_viewed:'Просмотр тура',checkout_started:'Начал бронирование',payment_returned:'Вернулся после оплаты',booking_confirmed:'Бронирование подтверждено'}
</script>
<style scoped>.head-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.head-actions .select{min-width:120px}.btn:disabled{opacity:.55;cursor:not-allowed}</style>
